/**
 * Contract, answers side: the fixtures are real answers of the API (generated by
 * backend/src/tests/integration/contract.test.ts). Each one must fit the type the app
 * declares for it, and the type must not ignore a field the API sends. A change on either
 * side fails `tsc` (and `typecheck.test.ts`, which runs it from Jest) until both agree again.
 */
import type {
  AuthResult,
  TwoFactorChallenge,
  TwoFactorSetup,
  TwoFactorStatus,
} from '@modules/auth/domain/types';
import type { BillingOverview, PlanCatalog, ReferralSummary } from '@modules/billing/domain/types';
import type {
  Account,
  AnnualSummary,
  AutonomoCloudCopy,
  AutonomoDraft,
  BusinessCategory,
  Category,
  CategoryBudget,
  Goal,
  ImportResult,
  SampleDataStatus,
  LeakFinding,
  MoneyLeaks,
  MonthOverview,
  Transaction,
  TransactionSearchResult,
  UserSettings,
  YearTax,
} from '@modules/finances/domain/types';
import type { AutonomoSaved } from '@modules/finances/ui/components/autonomoSync';
import type {
  CryptoCandles,
  CryptoLive,
  CryptoCoins,
  CryptoRanking,
  PriceAlerts,
  SeasonReport,
  SimPortfolio,
} from '@modules/crypto/domain/types';
import type { CryptoDrawings } from '@modules/crypto/domain/drawings';
import { cryptoAlerts } from './fixtures/cryptoAlerts';
import { cryptoDrawings } from './fixtures/cryptoDrawings';
import { cryptoRanking } from './fixtures/cryptoRanking';
import { cryptoReport } from './fixtures/cryptoReport';
import { contract } from './exact';
import { cryptoCandles } from './fixtures/cryptoCandles';
import { cryptoLive } from './fixtures/cryptoLive';
import { cryptoCoins } from './fixtures/cryptoCoins';
import { cryptoSim } from './fixtures/cryptoSim';
import { cryptoSimFilled } from './fixtures/cryptoSimFilled';
import { cryptoSimTransferred } from './fixtures/cryptoSimTransferred';
import { accounts } from './fixtures/accounts';
import { annualSummary } from './fixtures/annualSummary';
import { authResult } from './fixtures/authResult';
import { autonomoData } from './fixtures/autonomoData';
import { autonomoDraft } from './fixtures/autonomoDraft';
import { autonomoSaved } from './fixtures/autonomoSaved';
import { avatarChange } from './fixtures/avatarChange';
import { billingOverview } from './fixtures/billingOverview';
import { budgets } from './fixtures/budgets';
import { businessCategories } from './fixtures/businessCategories';
import { categories } from './fixtures/categories';
import { goals } from './fixtures/goals';
import { leakDecision } from './fixtures/leakDecision';
import { moneyLeaks } from './fixtures/moneyLeaks';
import { importResult } from './fixtures/importResult';
import { sampleData } from './fixtures/sampleData';
import { monthOverview } from './fixtures/monthOverview';
import { nameChange } from './fixtures/nameChange';
import { planCatalog } from './fixtures/planCatalog';
import { referralSummary } from './fixtures/referralSummary';
import { settings } from './fixtures/settings';
import { transaction } from './fixtures/transaction';
import { transactionSearch } from './fixtures/transactionSearch';
import { twoFactorChallenge } from './fixtures/twoFactorChallenge';
import { twoFactorEnabled } from './fixtures/twoFactorEnabled';
import { twoFactorSetup } from './fixtures/twoFactorSetup';
import { twoFactorStatus } from './fixtures/twoFactorStatus';
import { twoFactorStatusOn } from './fixtures/twoFactorStatusOn';
import { yearTax } from './fixtures/yearTax';

describe('API answers fit the types of the app', () => {
  it('months and movements', () => {
    contract<MonthOverview>()(monthOverview);
    contract<Transaction>()(transaction);
    contract<AnnualSummary>()(annualSummary);
    contract<TransactionSearchResult>()(transactionSearch);
    contract<Category[]>()(categories);
    contract<CategoryBudget[]>()(budgets);
    contract<UserSettings>()(settings);
    contract<{ accounts: Account[]; total: number }>()(accounts);
    contract<Goal[]>()(goals);
    contract<MoneyLeaks>()(moneyLeaks);
    contract<LeakFinding>()(leakDecision);
    contract<ImportResult>()(importResult);
    contract<SampleDataStatus>()(sampleData);
    expect(monthOverview.transactions.length).toBeGreaterThan(0);
  });

  it('plans and referrals', () => {
    contract<BillingOverview>()(billingOverview);
    contract<PlanCatalog>()(planCatalog);
    contract<ReferralSummary>()(referralSummary);
    expect(planCatalog.currency).toBe('EUR');
  });

  it('sign-in, profile and two-step verification', () => {
    contract<AuthResult>()(authResult);
    contract<{ name: string }>()(nameChange);
    contract<{ avatar: string | null }>()(avatarChange);
    contract<TwoFactorStatus>()(twoFactorStatus);
    contract<TwoFactorStatus>()(twoFactorStatusOn);
    contract<TwoFactorSetup>()(twoFactorSetup);
    contract<{ recoveryCodes: string[] }>()(twoFactorEnabled);
    contract<TwoFactorChallenge>()(twoFactorChallenge);
    expect(authResult.user.email).toBe('ana@example.com');
  });

  it('self-employed', () => {
    contract<AutonomoCloudCopy>()(autonomoData);
    // What the account keeps is exactly what the form code sends: the saved form type.
    contract<AutonomoSaved>()(autonomoData.data);
    contract<{ version: number; updatedAt: string }>()(autonomoSaved);
    contract<BusinessCategory[]>()(businessCategories);
    contract<YearTax>()(yearTax);
    contract<AutonomoDraft>()(autonomoDraft);
    expect(autonomoData.version).toBe(2);
  });

  it('crypto console', () => {
    contract<CryptoCoins>()(cryptoCoins);
    contract<CryptoCandles>()(cryptoCandles);
    contract<CryptoLive>()(cryptoLive);
    contract<SimPortfolio>()(cryptoSim);
    contract<SimPortfolio>()(cryptoSimFilled);
    contract<SimPortfolio>()(cryptoSimTransferred);
    contract<CryptoRanking>()(cryptoRanking);
    contract<PriceAlerts>()(cryptoAlerts);
    contract<CryptoDrawings>()(cryptoDrawings);
    contract<SeasonReport>()(cryptoReport);
    expect(cryptoSim.pending.length).toBeGreaterThan(0);
    expect(cryptoSimFilled.fills).toHaveLength(1);
  });
});
